// Filter buttons shown at the top — edit labels/values freely.
const FILTERS = [
  { label: "All", value: "all" },
  { label: "Clothing", value: "clothing" },
  { label: "Watches", value: "watches" },
  { label: "Men", value: "men" },
  { label: "Women", value: "women" },
];

// Currency conversion — fixed rates, edit these to update.
// All prices in POSTS above are entered in USD; other currencies are
// calculated from these rates. Update the numbers here any time rates change.
const CURRENCIES = {
  USD: { symbol: "$", rate: 1 },
  EUR: { symbol: "€", rate: 0.92 },
  GBP: { symbol: "£", rate: 0.79 },
  INR: { symbol: "₹", rate: 83.2 },
};

const TILTS = [-3, 2, -1.5, 3, -2.5, 1.5, -1, 2.5];
let currentFilter = "all";
let currentCurrency = "USD";

function formatPrice(usdAmount) {
  const c = CURRENCIES[currentCurrency];
  const converted = usdAmount * c.rate;
  const decimals = currentCurrency === "INR" ? 0 : 2;
  return `${c.symbol}${converted.toFixed(decimals)}`;
}

function renderFilters() {
  const el = document.getElementById("tagFilters");
  el.innerHTML = "";
  FILTERS.forEach((f) => {
    const btn = document.createElement("button");
    btn.className = "tag-btn" + (f.value === currentFilter ? " active" : "");
    btn.textContent = f.label;
    btn.onclick = () => {
      currentFilter = f.value;
      renderFilters();
      renderBoard();
    };
    el.appendChild(btn);
  });
}

function renderBoard() {
  const board = document.getElementById("board");
  board.innerHTML = "";
  const grid = document.createElement("div");
  grid.className = "grid";

  const visible = POSTS.filter(
    (p) => currentFilter === "all" || p.tags.includes(currentFilter)
  );

  visible.forEach((post) => {
    const cheapest = Math.min(...post.products.map((p) => p.price));
    const card = document.createElement("button");
    card.className = "pin-card";
    card.style.transform = `rotate(${TILTS[post.id % TILTS.length]}deg)`;
    card.onclick = () => openDrawer(post);

    card.innerHTML = `
      <div class="pushpin"></div>
      <div class="img-wrap">
        <img src="${post.image}" alt="${post.caption}" />
        <div class="category-badge">${post.tags[0]}</div>
        <div class="price-tag">from ${formatPrice(cheapest)}</div>
      </div>
      <p class="caption">${post.caption}</p>
      <p class="item-count">${post.products.length} item${post.products.length > 1 ? "s" : ""} tagged</p>
    `;
    grid.appendChild(card);
  });

  board.appendChild(grid);
}

function openDrawer(post) {
  document.getElementById("drawerTitle").textContent = post.caption;
  const itemsEl = document.getElementById("drawerItems");
  itemsEl.innerHTML = "";

  let total = 0;
  post.products.forEach((p) => {
    total += p.price;
    const a = document.createElement("a");
    a.className = "drawer-item";
    a.href = p.url;
    a.target = "_blank";
    a.rel = "noopener noreferrer";
    a.innerHTML = `
      <div>
        <p class="name">${p.name}</p>
        <p class="price">${formatPrice(p.price)}</p>
      </div>
      <span class="buy">Buy &nearr;</span>
    `;
    itemsEl.appendChild(a);
  });

  document.getElementById("itemCount").textContent = `${post.products.length} items shown`;
  document.getElementById("totalPrice").textContent = `Total ${formatPrice(total)}`;
  document.getElementById("overlay").classList.add("open");
  activePost = post; // keep reference so we can re-render prices on currency change
}

let activePost = null;

document.getElementById("closeDrawer").onclick = () =>
  document.getElementById("overlay").classList.remove("open");
document.getElementById("overlay").onclick = (e) => {
  if (e.target.id === "overlay") e.target.classList.remove("open");
};

document.getElementById("year").textContent = new Date().getFullYear();

document.getElementById("currencySelect").onchange = (e) => {
  currentCurrency = e.target.value;
  renderBoard();
  if (activePost) openDrawer(activePost); // refresh open drawer's prices too
};

renderFilters();
renderBoard();
